package glitch

import data.glitch_lib

# Weak encryption algorithms
weak_algorithms := {"DES", "3DES", "TDES", "RC2", "RC4", "Blowfish", "MD5", "SHA1", "SHA-1", "RSA-1024", "DSA", "ECB", "PKCS#1v1.5", "XOR", "ROT13", "null", "none", "plaintext"}

# Weak protocols
weak_protocols := {"SSLv3", "TLSv1", "TLSv1.1", "SSL", "TLS1.0", "TLS1.1", "ssl_policy", "tls_policy"}

# Encryption-related field names
encryption_fields := {"encryption_algorithm", "algorithm", "cipher", "cipher_suite", "ssl_policy", "tls_policy", "protocol", "minimum_protocol_version", "signature_algorithm", "key_algorithm", "sse_algorithm", "hash_algorithm", "digest_algorithm", "mac_algorithm"}

# Key size field names
key_size_fields := {"key_length", "key_size", "bits", "strength", "key_bits", "key_length_bits", "size", "length"}

# Encryption enabled fields
enabled_fields := {"encryption_at_rest", "encryption_in_transit", "storage_encrypted", "encrypted", "encryption_enabled", "server_side_encryption", "transparent_data_encryption", "fips_enabled", "rotation_enabled"}

# Helper to get string value from various node types
get_string_value(node) = value {
    node.ir_type == "String"
    value := node.value
} else = value {
    node.ir_type == "VariableReference"
    value := node.value
}

# Helper to get numeric value
get_numeric_value(node) = value {
    node.ir_type == "Integer"
    value := node.value
} else = value {
    node.ir_type == "Float"
    value := node.value
} else = value {
    node.ir_type == "String"
    value := to_number(node.value)
}

# Check if value contains weak algorithm
contains_weak_algorithm(value) {
    upper_val := upper(value)
    weak := weak_algorithms[_]
    contains(upper_val, weak)
}

# Check if value is weak protocol version
is_weak_protocol(value) {
    upper_val := upper(value)
    weak := weak_protocols[_]
    contains(upper_val, weak)
}

# Check if TLS version is weak (< 1.2)
is_weak_tls_version(value) {
    val := upper(value)
    val == "1.0"
} else {
    val := upper(value)
    val == "1.1"
} else {
    val := upper(value)
    contains(val, "TLS1.0")
} else {
    val := upper(value)
    contains(val, "TLS1.1")
} else {
    val := upper(value)
    contains(val, "TLS 1.0")
} else {
    val := upper(value)
    contains(val, "TLS 1.1")
} else {
    val := upper(value)
    regex.match("TLS[_-]?V?1\\.?(0|1)[^0-9]", val)
}

# Recursively collect all key-value pairs from complex values
collect_key_values(node, key_values) = result {
    node.ir_type == "Hash"
    result := {kv | kv := walk_hash(node)}
} else = result {
    node.ir_type == "Array"
    result := {kv | kv := walk_array(node)}
} else = result {
    node.ir_type == "KeyValue"
    result := {{node.name: node.value}}
} else = result {
    result := {{}}
}

walk_hash(node) = kv {
    some key
    val := node.value[key]
    key_str := get_string_value(key)
    kv := {"key": key_str, "value": val}
    val.ir_type != "Hash"
    val.ir_type != "Array"
}

walk_hash(node) = kv {
    some key
    val := node.value[key]
    key_str := get_string_value(key)
    inner := walk_hash(val)
    kv := {"key": sprintf("%s.%s", [key_str, inner.key]), "value": inner.value}
}

walk_hash(node) = kv {
    some key
    val := node.value[key]
    key_str := get_string_value(key)
    inner := walk_array(val)
    kv := {"key": sprintf("%s.%s", [key_str, inner.key]), "value": inner.value}
}

walk_array(node) = kv {
    some idx
    val := node.value[idx]
    kv := {"key": sprintf("[%d]", [idx]), "value": val}
    val.ir_type != "Hash"
    val.ir_type != "Array"
}

walk_array(node) = kv {
    some idx
    val := node.value[idx]
    inner := walk_hash(val)
    kv := {"key": sprintf("[%d].%s", [idx, inner.key]), "value": inner.value}
}

walk_array(node) = kv {
    some idx
    val := node.value[idx]
    inner := walk_array(val)
    kv := {"key": sprintf("[%d]%s", [idx, inner.key]), "value": inner.value}
}

# Extract all nested attributes from a value
all_nested_attrs(node) = attrs {
    node.ir_type == "Hash"
    attrs := {a | a := extract_from_hash(node, "")}
} else = attrs {
    node.ir_type == "Array"
    attrs := {a | a := extract_from_array(node, "")}
} else = attrs {
    attrs := {{"name": "", "value": node}}
}

extract_from_hash(node, prefix) = result {
    some key
    val := node.value[key]
    key_str := get_string_value(key)
    full_key := concat_dot(prefix, key_str)
    val.ir_type != "Hash"
    val.ir_type != "Array"
    result := {"name": full_key, "value": val}
}

extract_from_hash(node, prefix) = result {
    some key
    val := node.value[key]
    key_str := get_string_value(key)
    full_key := concat_dot(prefix, key_str)
    val.ir_type == "Hash"
    result := extract_from_hash(val, full_key)
}

extract_from_hash(node, prefix) = result {
    some key
    val := node.value[key]
    key_str := get_string_value(key)
    full_key := concat_dot(prefix, key_str)
    val.ir_type == "Array"
    result := extract_from_array(val, full_key)
}

extract_from_array(node, prefix) = result {
    some idx
    val := node.value[idx]
    full_key := sprintf("%s[%d]", [prefix, idx])
    val.ir_type != "Hash"
    val.ir_type != "Array"
    result := {"name": full_key, "value": val}
}

extract_from_array(node, prefix) = result {
    some idx
    val := node.value[idx]
    full_key := sprintf("%s[%d]", [prefix, idx])
    val.ir_type == "Hash"
    result := extract_from_hash(val, full_key)
}

extract_from_array(node, prefix) = result {
    some idx
    val := node.value[idx]
    full_key := sprintf("%s[%d]", [prefix, idx])
    val.ir_type == "Array"
    result := extract_from_array(val, full_key)
}

concat_dot(a, b) = result {
    a == ""
    result := b
} else = result {
    result := sprintf("%s.%s", [a, b])
}

# Check for weak encryption value in field
has_weak_encryption_value(attr) {
    val := get_string_value(attr.value)
    contains_weak_algorithm(val)
} else {
    val := get_string_value(attr.value)
    is_weak_protocol(val)
} else {
    val := get_string_value(attr.value)
    is_weak_tls_version(val)
} else {
    val := get_string_value(attr.value)
    regex.match("(?i)base64", val)
    contains(upper(val), "ENCRYPT")
}

# Check encryption disabled (Boolean false)
encryption_disabled(attr) {
    attr.value.ir_type == "Boolean"
    attr.value.value == false
}

# Check for small key size
has_weak_key_size(attr) {
    key_size_fields[_] == lower(attr.name)
    num_val := get_numeric_value(attr.value)
    num_val < 128
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check for encryption field with weak value
    lower_name := lower(attr.name)
    encryption_field := encryption_fields[_]
    contains(lower_name, encryption_field)
    has_weak_encryption_value(attr)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Weak or deprecated encryption algorithm detected. (CWE-326)"
    }
}

