package glitch

import data.glitch_lib

weak_algorithms := {"DES", "3DES", "TDES", "RC2", "RC4", "Blowfish", "MD5", "SHA1", "SHA-1", "RSA-1024", "DSA", "ECB", "PKCS#1V1.5", "XOR", "ROT13", "NULL", "NONE", "PLAINTEXT", "MD5_CRYPT", "SHA1CRYPT", "CBC", "CBC_SHA"}

weak_protocols := {"SSLV3", "TLSV1", "TLSV1.1", "SSL", "TLS1.0", "TLS1.1"}

encryption_related_fields := {"algorithm", "cipher", "cipher_suite", "ssl_policy", "tls_policy", "protocol", "minimum_protocol_version", "signature_algorithm", "key_algorithm", "sse_algorithm", "hash_algorithm", "digest_algorithm", "mac_algorithm", "encrypt", "encryption", "hash", "checksum", "verify_mode", "ssl_version", "tls_version", "enable_legacy"}

key_size_fields := {"key_length", "key_size", "bits", "strength", "key_bits", "salt_size"}

enabled_fields := {"encryption_at_rest", "encryption_in_transit", "storage_encrypted", "encrypted", "encryption_enabled", "server_side_encryption", "transparent_data_encryption", "fips_enabled", "rotation_enabled", "enable_advanced"}

is_encryption_related_field(name) {
    lower_name := lower(name)
    field := encryption_related_fields[_]
    contains(lower_name, field)
}

is_enabled_field(name) {
    lower_name := lower(name)
    field := enabled_fields[_]
    contains(lower_name, field)
}

is_key_size_field(name) {
    lower_name := lower(name)
    field := key_size_fields[_]
    contains(lower_name, field)
}

check_weak_value(val) {
    upper_val := upper(val)
    weak := weak_algorithms[_]
    contains(upper_val, weak)
} else {
    upper_val := upper(val)
    weak := weak_protocols[_]
    contains(upper_val, weak)
}

check_function_call_for_weak_crypto(node) {
    node.ir_type == "FunctionCall"
    func_name := lower(node.name)
    contains(func_name, "hash")
    arg := node.args[_]
    arg.ir_type == "String"
    check_weak_value(arg.value)
}

get_leaf_strings(node, vals) {
    node.ir_type == "String"
    vals := {node.value}
} else {
    node.ir_type == "VariableReference"
    vals := {node.value}
} else {
    node.ir_type == "FunctionCall"
    check_function_call_for_weak_crypto(node)
    vals := {"weak_crypto"}
} else {
    node.ir_type == "Hash"
    vals := {v |
        [_, kv] := walk(node)
        kv.ir_type == "KeyValue"
        leaf_vals := get_leaf_strings(kv.value, _)
        v := leaf_vals[_]
    }
} else {
    node.ir_type == "Array"
    vals := {v |
        [_, elem] := walk(node)
        leaf_vals := get_leaf_strings(elem, _)
        v := leaf_vals[_]
    }
} else {
    vals := set()
}

has_weak_value(node) {
    vals := get_leaf_strings(node, _)
    val := vals[_]
    check_weak_value(val)
}

has_weak_encryption_in_function_call(node) {
    node.ir_type == "FunctionCall"
    func_name := lower(node.name)
    contains(func_name, "hash")
    arg := node.args[_]
    arg.ir_type == "String"
    check_weak_value(arg.value)
}

encryption_disabled(node) {
    node.ir_type == "Boolean"
    node.value == false
} else {
    node.ir_type == "String"
    lower(node.value) == "no"
} else {
    node.ir_type == "String"
    lower(node.value) == "false"
}

has_weak_key_size(node) {
    node.ir_type == "Integer"
    node.value < 128
} else {
    node.ir_type == "String"
    num := to_number(trim(node.value, "\""))
    num < 128
}

any_keyvalue_has_encryption_related_name(node) {
    [_, n] := walk(node)
    n.ir_type == "KeyValue"
    is_encryption_related_field(n.name)
}

any_keyvalue_has_enabled_field_name(node) {
    [_, n] := walk(node)
    n.ir_type == "KeyValue"
    is_enabled_field(n.name)
}

any_keyvalue_has_key_size_field_name(node) {
    [_, n] := walk(node)
    n.ir_type == "KeyValue"
    is_key_size_field(n.name)
}

# Detect in atomic unit attributes
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    is_encryption_related_field(attr.name)
    has_weak_value(attr.value)
    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Weak or deprecated encryption algorithm detected. (CWE-326)"
    }
}

